        }

        void addChild(Node* node) {
            char c = text[node->start];
            children[c] = node;
        }
    };

    Node* root;
    Node* activeNode;
    int activeEdge;
    int activeLength;
    int remaining;

    string text;

public:
    SuffixTree(string text) {
        this->text = text;
        root = new Node(-1, -1);
        activeNode = root;
        activeEdge = -1;
        activeLength = 0;
        remaining = 0;
        build();
    }

